-- Staging residential recording context. No historical reports/templates are modified.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
CREATE TABLE public.ts_electrical_jobs (
 site_id uuid PRIMARY KEY, company_id uuid NOT NULL, document jsonb NOT NULL,
 revision integer NOT NULL CHECK(revision>0), updated_by uuid NOT NULL REFERENCES auth.users(id),
 updated_at timestamptz NOT NULL DEFAULT now(), credential_check jsonb, internal_review jsonb,
 FOREIGN KEY(company_id,site_id) REFERENCES public.ts_sites(company_id,id)
);
CREATE TABLE public.ts_electrical_job_versions (
 site_id uuid NOT NULL REFERENCES public.ts_electrical_jobs(site_id), company_id uuid NOT NULL REFERENCES public.ts_companies(id),
 revision integer NOT NULL, snapshot jsonb NOT NULL, recorded_by uuid NOT NULL REFERENCES auth.users(id),
 recorded_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(site_id,revision)
);
ALTER TABLE public.ts_electrical_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ts_electrical_job_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY electrical_read ON public.ts_electrical_jobs FOR SELECT TO authenticated USING(public.ts_role(company_id) IS NOT NULL);
CREATE POLICY electrical_version_read ON public.ts_electrical_job_versions FOR SELECT TO authenticated USING(public.ts_role(company_id) IS NOT NULL);
REVOKE ALL ON public.ts_electrical_jobs,public.ts_electrical_job_versions FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.ts_electrical_jobs,public.ts_electrical_job_versions TO authenticated;
CREATE TRIGGER electrical_versions_immutable BEFORE UPDATE OR DELETE ON public.ts_electrical_job_versions FOR EACH ROW EXECUTE FUNCTION public.ts_immutable();

